from __future__ import annotations

import argparse
import json
from pathlib import Path

from agentic_plc.evaluation import (
    ConsistencyBenchmarkRunner,
    load_benchmark_cases,
    write_benchmark_payload,
)


def main() -> int:
    parser = argparse.ArgumentParser(
        description=(
            "Run protocol/physical consistency benchmark cases from a JSON "
            "artifact generated by this project or by a dataset importer."
        )
    )
    parser.add_argument(
        "--input",
        type=Path,
        required=True,
        help="Benchmark JSON containing a top-level cases list.",
    )
    parser.add_argument(
        "--output",
        type=Path,
        help="Optional JSON output path for cases plus report.",
    )
    parser.add_argument(
        "--allow-failures",
        action="store_true",
        help="Exit with status 0 even when benchmark checks fail.",
    )
    args = parser.parse_args()

    cases = load_benchmark_cases(args.input)
    report = ConsistencyBenchmarkRunner().run(cases)
    payload = {
        "cases": [case.to_dict() for case in cases],
        "report": report.to_dict(),
    }
    text = json.dumps(payload, indent=2, sort_keys=True)
    if args.output is not None:
        write_benchmark_payload(args.output, payload)
    print(text)
    if report.passed or args.allow_failures:
        return 0
    return 1


if __name__ == "__main__":
    raise SystemExit(main())
